import{d as c,C as r,o as q,c as P,a3 as l,E as t,j as i,a as e}from"./chunks/framework.Q4yG9rk_.js";const D=JSON.parse('{"title":"孟子·梁惠王上","description":"《孟子》第 1 篇「梁惠王上」——七节分节精读。何必曰利、贤者与民偕乐、五十步笑百步、率兽而食人、仁者无敌、不嗜杀人者能一之，与全书极长章「齐桓晋文之事」。","frontmatter":{"title":"孟子·梁惠王上","description":"《孟子》第 1 篇「梁惠王上」——七节分节精读。何必曰利、贤者与民偕乐、五十步笑百步、率兽而食人、仁者无敌、不嗜杀人者能一之，与全书极长章「齐桓晋文之事」。","category":"guide","aliases":["梁惠王上","梁惠王章句上","mengzi 梁惠王上"],"source":["《孟子》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/mengzi/chapter-01.md","filePath":"lizhimingde/sishu-wujing/mengzi/chapter-01.md","lastUpdated":1790316338000}'),T={name:"lizhimingde/sishu-wujing/mengzi/chapter-01.md"},C=c({...T,setup(k){const o=[{id:"jie1_s1",label:"孟子见梁惠王",showLabel:!0,sentences:[["孟子见梁惠王。王曰：“叟！不远千里而来，亦将有以利吾国乎？”"]],note:"孟子去见梁惠王。梁惠王开口就问：「老先生，您不远千里到这里来，想必有什么对我的国家有利的办法吧？」这一问，就带出了全书第一个、也是最根本的话题——「利」与「义」之辨。"},{id:"jie1_s2",label:"王何必曰利",showLabel:!0,sentences:[["孟子对曰：“王何必曰利？亦有仁义而已矣。王曰：‘何以利吾国？’大夫曰：‘何以利吾家？’士庶人曰：‘何以利吾身？’上下交征利而国危矣。",{text:"万乘之国",glossary:"wansheng"},"，弑其君者，必千乘之家；千乘之国，弑其君者，必百乘之家。万取千焉，千取百焉，不为不多矣。苟为后义而先利，不夺不",{text:"餍",glossary:"yan-man"},"。未有仁而遗其亲者也，未有义而后其君者也。王亦曰仁义而已矣，何必曰利？”"]],note:"孟子回答：大王何必谈利呢？只要有仁义就够了。假若君王说「怎样有利于我的国家」，大夫说「怎样有利于我的封地」，士人和百姓说「怎样有利于我自己」，上上下下都争利，国家就危险了。在拥有万辆兵车的国家里，杀掉国君的，一定是拥有千辆兵车的大夫之家；在拥有千辆兵车的国家里，杀掉国君的，一定是拥有百辆兵车的大夫之家——一万辆里取一千辆、一千辆里取一百辆，不能说不多。但如果把义抛在后面、把利摆在前面，不全部夺取是不会满足的。反过来看，从来没有讲仁的人会遗弃父母，也没有讲义的人会怠慢君主。所以，大王只要讲仁义就行了，何必谈利？"}],g=[{id:"wansheng",term:"万乘之国",pinyin:"wàn shèng zhī guó",meaning:"拥有万辆兵车的大国。乘：一车四马。下文千乘、百乘依此递减，千乘之家指大夫，百乘之家指更小的采邑之主。"},{id:"yan-man",term:"餍",pinyin:"yàn",meaning:"满足。不夺不餍：不夺取就不会满足。"}],m=[{id:"jie2_s1",label:"王立于沼上",showLabel:!0,sentences:[["孟子见梁惠王。王立于",{text:"沼",glossary:"zhao-chi"},"上，顾鸿雁麋鹿，曰：“贤者亦乐此乎？”"]],note:"孟子去见梁惠王。梁惠王正站在池塘边，看着鸿雁麋鹿，问道：「贤人也以此为乐吗？」这一问，引出孟子对「乐」的一番辨析。"},{id:"jie2_s2",label:"贤者而后乐此",showLabel:!0,sentences:[["孟子对曰：“贤者而后乐此，不贤者虽有此，不乐也。《诗》云：‘经始灵台，经之营之，庶民攻之，不日成之。经始勿亟，庶民子来。王在灵囿，",{text:"麀鹿",glossary:"youlu"},"攸伏，麀鹿濯濯，白鸟翯翯。王在灵沼，於牣鱼跃。’文王以民力为台为沼，而民欢乐之，谓其台曰灵台，谓其沼曰灵沼，乐其有麋鹿鱼鳖。古之人与民偕乐，故能乐也。《汤誓》曰：‘时日",{text:"曷",glossary:"he-he"},"丧，予及女偕亡。’民欲与之偕亡，虽有台池鸟兽，岂能独乐哉？”"]],note:"孟子回答：贤人才能享受这种快乐，不贤的人纵然有这些，也快乐不起来。他引《诗》说文王当初筑灵台、挖灵沼，百姓像给自家干活一样踊跃，还把台、沼叫作「灵台」「灵沼」，为文王有麋鹿鱼鳖而高兴——因为文王和大家一同快乐，所以能真正快乐。他又引《汤誓》里百姓咒骂夏桀的话：「这个太阳什么时候灭亡？我们宁愿跟你一起死！」百姓恨不得和君主同归于尽，那么即便有高台深池、珍禽异兽，他还能独自快乐吗？"}],h=[{id:"zhao-chi",term:"沼",pinyin:"zhǎo",meaning:"水池。王立于沼上：梁惠王站在池边看鸿雁麋鹿。"},{id:"youlu",term:"麀鹿",pinyin:"yōu lù",meaning:"母鹿。麀：母兽。"},{id:"he-he",term:"曷",pinyin:"hé",meaning:"何时。时日曷丧：这个太阳什么时候才灭亡？（《汤誓》引文，人民诅咒夏桀之语）"}],u=[{id:"jie3_s1",label:"寡人之于国也",showLabel:!0,sentences:[["梁惠王曰：“寡人之于国也，尽心焉耳矣。河内凶，则移其民于河东，移其粟于河内。河东凶亦然。察邻国之政，无如寡人之用心者。邻国之民不加少，寡人之民不加多，何也？”"]],note:"梁惠王说：「我治理国家，算是尽心了。河内闹灾荒，就把河内百姓迁到河东、把河东粮食运到河内；河东闹灾荒也一样办。看邻国的政治，没有像我这样用心的。可是邻国百姓不见减少，我的百姓不见增多，为什么？」这一问，引出下文「五十步笑百步」的比喻。"},{id:"jie3_s2",label:"五十步笑百步",showLabel:!0,sentences:[["孟子对曰：“王好战，请以战喻。填然鼓之，兵刃既接，弃甲曳兵而走。或百步而后止，或五十步而后止。以五十步笑百步，则何如？”曰：“不可。直不百步耳，是亦走也。”"]],note:"孟子回答：大王喜欢打仗，请允许我用打仗来打比方。战鼓咚咚一响，刀锋相接，士兵们丢下盔甲、拖着兵器往后退，有的跑了一百步才停，有的跑了五十步才停。跑五十步的笑话跑一百步的，怎么样？王说：不行，只不过没跑到一百步而已，那也是逃跑啊。这话里藏着一层讽刺：大王治理国家与邻国相比，也不过是五十步与百步之差。"},{id:"jie3_s3",label:"养生丧死无憾，王道之始",showLabel:!0,sentences:[["曰：“王如知此，则无望民之多于邻国也。不违农时，谷不可胜食也；",{text:"数罟",glossary:"shugu"},"不入",{text:"洿池",glossary:"wuchi"},"，鱼鳖不可胜食也；斧斤以时入山林，材木不可胜用也。谷与鱼鳖不可胜食，材木不可胜用，是使民养生丧死无憾也。养生丧死无憾，王道之始也。"],["五亩之宅，树之以桑，五十者可以衣帛矣。鸡豚狗彘之畜，无失其时，七十者可以食肉矣。百亩之田，勿夺其时，数口之家可以无饥矣。谨",{text:"庠序",glossary:"xiangxu"},"之教，申之以孝悌之义，",{text:"颁白者",glossary:"banbaizhe"},"不负戴于道路矣。七十者衣帛食肉，黎民不饥不寒，然而不王者，未之有也。"],["狗彘食人食而不知检，涂有饿",{text:"莩",glossary:"piao"},"而不知发；人死，则曰：‘非我也，岁也。’是何异于刺人而杀之，曰：‘非我也，兵也。’王无罪岁，斯天下之民至焉。”"]],note:"孟子接着说：大王如果懂得这个道理，就别指望自己的百姓比邻国多。然后他讲起「王道之始」：不耽误农时，粮食就吃不完；不用密网下深池，鱼鳖就吃不完；按季节入山伐木，木材就用不完——这就让百姓养生送死都没有遗憾，这是王道的开端。再往下：五亩宅地种上桑树，五十岁的人可以穿丝绵；鸡狗猪不误时节饲养，七十岁的人可以吃肉；百亩田地不耽误农时，几口之家不会挨饿；办好学校教育，反复讲清孝顺父母、敬爱兄长的道理，头发花白的老人就不必在路上背负重物。最后他痛斥当时的虐政：猪狗吃着人的粮食却不知节制，路上有饿死的人却不知开仓赈济，人死了就说「不是我的过错，是年成不好」——这跟拿刀把人杀死，却说「不是我杀的，是刀杀的」有什么区别？"}],d=[{id:"shugu",term:"数罟",pinyin:"cù gǔ",meaning:"细密的渔网。数：密；罟：网。不入洿池：不许下到深池里（以免把小鱼也捞尽）。"},{id:"wuchi",term:"洿池",pinyin:"wū chí",meaning:"低洼的深水池。"},{id:"xiangxu",term:"庠序",pinyin:"xiáng xù",meaning:"古代学校的名称。殷代称序，周代称庠。"},{id:"banbaizhe",term:"颁白者",pinyin:"bān bái zhě",meaning:"颁：同「斑」。头发花白的老人。不负戴于道路：不必再在路上背负重物。"},{id:"piao",term:"莩",pinyin:"piǎo",meaning:"同「殍」，饿死的人。涂有饿莩：路上有饿死的人。"}],p=[{id:"jie4_s1",label:"杀人以梃与刃",showLabel:!0,sentences:[["梁惠王曰：“寡人愿安承教。”"],["孟子对曰：“杀人以",{text:"梃",glossary:"ting"},"与刃，有以异乎？”"],["曰：“无以异也。”"],["“以刃与政，有以异乎？”"],["曰：“无以异也。”"]],note:"梁惠王说：「我愿诚心接受您的指教。」孟子于是问：「用棍棒杀人和用刀杀人，有什么不同吗？」王说没有不同。孟子又追问：「用刀杀人和用政治杀人，有什么不同吗？」王说也没有不同。三问层层逼进。"},{id:"jie4_s2",label:"率兽而食人",showLabel:!0,sentences:[["曰：“庖有肥肉，厩有肥马，民有饥色，野有饿莩，此率兽而食人也。兽相食，且人恶之；为民父母，行政，不免于率兽而食人，恶在其为民父母也！仲尼曰：‘始作",{text:"俑",glossary:"yong"},"者，其无后乎！’为其象人而用之也。如之何其使斯民饥而死也？”"]],note:"孟子接着说：厨房里有肥肉，马厩里有壮马，可百姓面有饥色、野外有饿死的人——这等于是在率领禽兽来吃人。禽兽互相吞食，人尚且厌恶；身为百姓的父母官，治理政事却不免于率兽吃人，那怎么能做百姓的父母官呢？孔子说过：「最早用木偶陶俑陪葬的人，该断子绝孙吧！」就因为那俑像人形却被用来陪葬。那么，又怎么能眼睁睁让百姓饿死呢？"}],y=[{id:"ting",term:"梃",pinyin:"tǐng",meaning:"棍棒。以梃与刃：用棍棒杀人和用刀杀人。"},{id:"yong",term:"俑",pinyin:"yǒng",meaning:"殉葬用的木偶、陶俑。始作俑者，其无后乎：最早做俑来陪葬的人，该断子绝孙吧——因为俑像人形而用来殉葬。"}],b=[{id:"jie5_s1",label:"晋国天下莫强焉",showLabel:!0,sentences:[["梁惠王曰：“晋国，天下莫强焉，叟之所知也。及寡人之身，东败于齐，长子死焉；西丧地于秦七百里；南辱于楚。寡人耻之，愿",{text:"比死者一洒之",glossary:"bi-si"},"，如之何则可？”"]],note:"梁惠王说：「想当年，我们晋国天下没有比它更强的，这是您知道的。可传到我这一代，东边被齐国打败，大儿子战死；西边被秦国夺去七百里地；南边又受楚国的侮辱。我以此为耻，希望能替所有战死的人报仇雪恨一次，该怎么办才行？」"},{id:"jie5_s2",label:"仁者无敌",showLabel:!0,sentences:[["孟子对曰：“地方百里而可以王。王如施仁政于民，省刑罚，薄税敛，深耕易",{text:"耨",glossary:"nou"},"。壮者以暇日修其孝悌忠信，入以事其父兄，出以事其长上，可使制梃以挞秦楚之坚甲利兵矣。彼夺其民时，使不得耕耨以养其父母，父母冻饿，兄弟妻子离散。彼陷溺其民，王往而征之，夫谁与王敌？故曰：‘仁者无敌。’王请勿疑！”"]],note:"孟子回答：只要有方圆百里的地方就能称王天下。大王若对百姓施行仁政——减轻刑罚、削减赋税、深耕细作及时除草，再让壮年在农闲时修养孝顺父母、敬爱兄长、忠诚守信的品德，在家能服事父兄、在外能服事尊长——那就可以让他们拿着木棒去打击秦、楚的坚甲利兵了。因为秦楚侵夺百姓的农时，使他们不能耕种来赡养父母，父母受冻挨饿，兄弟妻儿离散。它们这般坑害自己的百姓，大王前去征讨，还有谁来与大王为敌呢？所以说：仁的人是天下无敌的，请大王不要怀疑。"}],x=[{id:"nou",term:"耨",pinyin:"nòu",meaning:"锄草。深耕易耨：深耕土地，及时除草。易：整治、及时。"},{id:"bi-si",term:"比死者一洒之",pinyin:"bǐ sǐ zhě yī xǐ zhī",meaning:"比：为、替。为所有战死者报仇雪耻一次。洒：同「洗」。"}],z=[{id:"jie6_s1",label:"望之不似人君",showLabel:!0,sentences:[["孟子见梁襄王。出，语人曰：“望之不似人君，就之而不见所畏焉。卒然问曰：‘天下恶乎定？’吾对曰：‘定于一。’‘孰能一之？’对曰：‘不嗜杀人者能一之。’‘孰能与之？’对曰：‘天下莫不与也。"],["王知夫苗乎？七八月之间旱，则苗槁矣。天油然作云，沛然下雨，则苗",{text:"浡然",glossary:"boran"},"兴之矣。其如是，孰能御之？今夫天下之",{text:"人牧",glossary:"renmu"},"，未有不嗜杀人者也，如有不嗜杀人者，则天下之民皆引领而望之矣。诚如是也，民归之，由水之就下，沛然谁能御之？’”"]],note:"孟子见了梁襄王。出来后对人说：「远看不像个国君，靠近也感觉不到可敬畏的地方。」梁襄王突然问他：「天下怎样才能安定？」孟子答：「统一了就会安定。」又问：「谁能统一它？」答：「不喜好杀人的可以统一。」又问：「谁会归附他？」答：「天下没有不归附的。」接着孟子打了个比方：大王知道禾苗吗？七八月间天旱，禾苗就枯萎；一旦天上涌起浓云、下起大雨，禾苗就蓬勃生长，谁挡得住？当今天下的君主，没有一个不喜好杀人。如果能有一个不喜好杀人的，那么天下的百姓都会伸长了脖子盼望他，归附他就像水往低处流，浩浩荡荡，谁能阻挡？"}],j=[{id:"boran",term:"浡然",pinyin:"bó rán",meaning:"兴起、蓬勃的样子。苗浡然兴之：禾苗蓬勃地生长起来。"},{id:"renmu",term:"人牧",pinyin:"rén mù",meaning:"统治人民的人（牧：牧养，引申为治理）。"}],w=[{id:"jie7_s1",label:"则王乎",showLabel:!0,sentences:[["齐宣王问曰：“齐桓、晋文之事可得闻乎？”"],["孟子对曰：“仲尼之徒无道桓、文之事者，是以后世无传焉。臣未之闻也。无以，则王乎？”"]],note:"齐宣王问：「齐桓公、晋文公的事，可以讲给我听听吗？」孟子回答：孔子的门徒没有谈齐桓公、晋文公的，所以后世没有流传，我也没有听说过。如果一定要说，那就谈谈王道吧？这一问，开启了《孟子》全书最长的一节。"},{id:"jie7_s2",label:"以羊易之",showLabel:!0,sentences:[["曰：“德何如，则可以王矣？”曰：“保民而王，莫之能御也。”曰：“若寡人者，可以保民乎哉？”曰：“可。”曰：“何由知吾可也？”曰：“臣闻之胡龁曰，王坐于堂上，有牵牛而过堂下者，王见之，曰：‘牛何之？’对曰：‘将以",{text:"衅钟",glossary:"xinzhong"},"。’王曰：‘舍之！吾不忍其",{text:"觳觫",glossary:"husu"},"，若无罪而就死地。’对曰：‘然则废衅钟与？’曰：‘何可废也？以羊易之！’不识有诸？”曰：“有之。”曰：“是心足以王矣。百姓皆以王为爱也，臣固知王之不忍也。”王曰：“然。诚有百姓者。齐国虽",{text:"褊小",glossary:"bianxiao"},"，吾何爱一牛？即不忍其觳觫，若无罪而就死地，故以羊易之也。”曰：“王无异于百姓之以王为爱也。以小易大，彼恶知之？王若隐其无罪而就死地，则牛羊何择焉？”王笑曰：“是诚何心哉？我非爱其财。而易之以羊也，宜乎百姓之谓我爱也。”"],["曰：“无伤也，是乃仁术也，见牛未见羊也。君子之于禽兽也，见其生，不忍见其死；闻其声，不忍食其肉。是以君子远庖厨也。”"],["王说曰：“《诗》云：‘他人有心，予忖度之。’夫子之谓也。夫我乃行之，反而求之，不得吾心。夫子言之，于我心有戚戚焉。此心之所以合于王者，何也？”"]],note:"宣王问：「要有怎样的德行才能称王？」孟子答：「安抚百姓而称王，就没有人能阻挡。」宣王问自己能不能做到，孟子说能，于是讲了「以羊易牛」的事：大王坐在堂上，看见有人牵着牛从堂下走过，问「牛牵到哪里去」，回答说「要用它祭钟」。大王说：「放了它！我不忍心看它哆嗦的样子，就像没罪的人被押往死地。」又问是不是要废掉祭钟之礼，大王说：「怎么可以废掉？用羊换它吧。」孟子说：有这份不忍之心，就足以称王天下了。百姓都以为大王是吝啬，我本来就知道大王是不忍心。"},{id:"jie7_s3",label:"不为也，非不能也",showLabel:!0,sentences:[["曰：“有复于王者曰：‘吾力足以举百钧’，而不足以举一羽；‘明足以察秋毫之末’，而不见舆薪，则王许之乎？”"],["曰：“否。”"],["“今恩足以及禽兽，而功不至于百姓者，独何与？然则一羽之不举，为不用力焉；舆薪之不见，为不用明焉，百姓之不见保，为不用恩焉。故王之不王，不为也，非不能也。”"],["曰：“不为者与不能者之形何以异？”"],["曰：“挟太山以超北海，语人曰‘我不能’，是诚不能也。为长者",{text:"折枝",glossary:"zheji"},"，语人曰‘我不能’，是不为也，非不能也。故王之不王，非挟太山以超北海之类也；王之不王，是折枝之类也。”"],["“老吾老，以及人之老；幼吾幼，以及人之幼。天下可运于掌。《诗》云：‘刑于寡妻，至于兄弟，以御于家邦。’言举斯心加诸彼而已。故推恩足以保四海，不推恩无以保妻子。古之人所以大过人者无他焉，善推其所为而已矣。今恩足以及禽兽，而功不至于百姓者，独何与？”"],["“权，然后知轻重；度，然后知长短。物皆然，心为甚。王请度之！抑王兴甲兵，危士臣，构怨于诸侯，然后快于心与？”"]],note:"孟子打了个比方：如果有人向大王报告——我的力气能举起三千斤，却举不起一根羽毛；眼力能看清秋天鸟兽新生细毛的末端，却看不见一整车柴火——大王会相信吗？王说不会。孟子接着说：如今大王的恩惠已经施到禽兽身上，功德却到不了百姓，这是为什么？一根羽毛举不起，是不肯使劲；一车柴火看不见，是不肯用眼；百姓得不到保护，是不肯施恩。所以大王没能称王天下，是「不肯做」，不是「做不到」。怎么区分呢？要你挟着泰山跨越北海，说「做不到」是真的；要你为老人折一根树枝，说「做不到」就是不肯。大王的没能称王，不属于挟泰山越北海那一类。最后孟子点出要害：敬爱自家的老人，也推及别人的老人；爱护自家的孩子，也推及别人的孩子——这样天下就能在手掌上运转了。"},{id:"jie7_s4",label:"缘木而求鱼",showLabel:!0,sentences:[["王曰：“否。吾何快于是？将以求吾所大欲也。”"],["曰：“王之所大欲可得闻与？”王笑而不言。"],["曰：“为肥甘不足于口与？轻暖不足于体与？抑为采色不足视于目与？声音不足听于耳与？便嬖不足使令于前与？王之诸臣皆足以供之，而王岂为是哉？”"],["曰：“否。吾不为是也。”"],["曰：“然则王之所大欲可知已。欲辟土地，朝秦楚，莅中国而抚四夷也。以若所为，求若所欲，犹",{text:"缘木而求鱼",glossary:"yuantong"},"也。”"],["王曰：“若是其甚与？”"],["曰：“殆有甚焉。缘木求鱼，虽不得鱼，无后灾。以若所为，求若所欲，尽心力而为之，后必有灾。”"],["曰：“可得闻与？”"],["曰：“邹人与楚人战，则王以为孰胜？”"],["曰：“楚人胜。”"],["曰：“然则小固不可以敌大，寡固不可以敌众，弱固不可以敌强。海内之地方千里者九，齐集有其一。以一服八，何以异于邹敌楚哉？盖亦反其本矣。"],["“今王发政施仁，使天下仕者皆欲立于王之朝，耕者皆欲耕于王之野，商贾皆欲藏于王之市，行旅皆欲出于王之涂，天下之欲疾其君者皆欲赴愬于王。其若是，孰能御之？”"]],note:"宣王说，我那样做是为了求我最想要的东西。孟子问他想要什么，王笑而不答。孟子逐一排除：是肥美的食物不够吃、轻暖的衣服不够穿、艳丽的色彩不够看、美妙的音乐不够听，还是身边的宠臣不够使唤？这些大王的臣子都能供给，大王难道是为了这些？王说，我不是为了这些。孟子于是点破：那么大王最想要的就可以知道了——是想扩张土地、让秦楚来朝、统治中原、安抚四夷。可是凭大王现在的做法去求这样的愿望，就像爬上树去捉鱼一样。王问：有那么严重吗？孟子说：恐怕还更严重。爬上树捉鱼，虽然捉不到鱼，却没有后患；凭您现在的做法去求那样的愿望，竭尽全力去做，日后必定有灾祸。"},{id:"jie7_s5",label:"制民之产",showLabel:!0,sentences:[["王曰：“吾惛，不能进于是矣。愿夫子辅吾志，明以教我，我虽不敏，请尝试之。”"],["曰：“无恒产而有恒心者，惟士为能。若民，则无恒产，因无恒心。苟无恒心，放辟邪侈无不为已。及陷于罪，然后从而刑之是",{text:"罔民",glossary:"wangmin"},"也。焉有仁人在位罔民而可为也？是故明君制民之产，必是仰足以事父母，俯足以畜妻子；乐岁终身饱，凶年免于死亡。然后驱而之善，故民之从之也轻。”"],["“今也制民之产，仰不足以事父母，俯不足以畜妻子；乐岁终身苦，凶年不免于死亡。此惟救死而恐不赡，奚暇治礼义哉？”"],["“王欲行之则盍反其本矣？五亩之宅，树之以桑，五十者可以衣帛矣。鸡豚狗彘之畜，无失其时，七十者可以食肉矣。百亩之田，勿夺其时，数口之家可以无饥矣。谨庠序之教，申之以孝悌之义，颁白者不负戴于道路矣。老者衣帛食肉，黎民不饥不寒，然而不王者，未之有也。”"]],note:"宣王说：「我糊涂，到不了这一步，希望先生帮助我达成心愿，明白地教导我。」孟子于是讲根本之策：没有固定的产业而有恒定的善心的，只有士人能做到；至于百姓，没有固定产业就没有恒定善心，一旦没有善心，就会胡作非为、无所不为。等他们犯了罪再加刑，这就是陷害百姓。哪有仁人当政却干陷害百姓的事呢？所以英明的君主规定百姓的产业，一定使他们上足以赡养父母、下足以养活妻儿，好年成一年到头吃得饱，坏年成也不至于饿死。然后再引导他们向善，百姓就容易听从了。最后他重申：五亩宅地种桑，五十岁可穿丝绵；鸡狗猪不误时节，七十岁可吃肉；百亩田地不夺农时，几口之家不挨饿；办好教育讲清孝悌，花白头发的老人不必在路上负重——老人们穿丝绵吃肉，百姓不饥不寒，这样还不能称王天下的，从来没有过。"}],f=[{id:"xinzhong",term:"衅钟",pinyin:"xìn zhōng",meaning:"古代新钟铸成，杀牲取血涂在钟的缝隙上以祭，称衅钟。"},{id:"husu",term:"觳觫",pinyin:"hú sù",meaning:"因恐惧而颤抖的样子。吾不忍其觳觫：我不忍心看它吓得发抖。"},{id:"bianxiao",term:"褊小",pinyin:"biǎn xiǎo",meaning:"狭小。齐国虽褊小：齐国虽然狭小。"},{id:"zheji",term:"折枝",pinyin:"zhé zhī",meaning:"为老人折一根树枝（一说「枝」通「肢」，指按摩肢体）。喻极易做到的事。"},{id:"yuantong",term:"缘木而求鱼",pinyin:"yuán mù ér qiú yú",meaning:"爬到树上去捉鱼。喻方向错了，白费力气。"},{id:"wangmin",term:"罔民",pinyin:"wǎng mín",meaning:"罔：同「网」，张网陷害。是罔民也：这是设罗网来陷害百姓。"}];return(L,n)=>{const s=r("DaoTextReading"),a=r("DaoKeywordCards");return q(),P("div",null,[n[0]||(n[0]=l('<h1 id="孟子·梁惠王上" tabindex="-1">孟子·梁惠王上 <a class="header-anchor" href="#孟子·梁惠王上" aria-label="Permalink to &quot;孟子·梁惠王上&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《梁惠王上》七节，是《孟子》的<strong>开篇定调之篇</strong>：六节是孟子与诸侯的对话（梁惠王 ×3、梁襄王 ×1、齐宣王 ×1，另有梁惠王立于沼上一节），一场一场辩下来，「仁政」的主张被反复推进。</p><p>读法：<strong>默认竹简模式</strong>，适合沉浸通读；切到右上角<strong>经典阅读</strong>，原文中的生词可点击查看释义。每节之下另附<strong>字词卡片</strong>。</p><hr><h3 id="一、何必曰利" tabindex="-1">一、何必曰利 <a class="header-anchor" href="#一、何必曰利" aria-label="Permalink to &quot;一、何必曰利&quot;">​</a></h3><p>全书的宣言就在这一节。梁惠王一开口问「利」，孟子一开口就把话顶回去：<strong>「王何必曰利？亦有仁义而已矣。」</strong> 接下来的推理很硬——上上下下互相争利，国家必危；而「未有仁而遗其亲者也，未有义而后其君者也」，是把仁义当成了更可靠的治理基础。</p>',7)),t(s,{sections:o,glossary:g,"default-mode":"slips","aria-label":"孟子·梁惠王上·第一节 原文"}),t(a,{items:[{term:"万乘之国",pinyin:["wàn","shèng","zhī","guó"],meaning:"拥有万辆兵车的大国。乘：一车四马。下文千乘、百乘依此递减，千乘之家指大夫，百乘之家指更小的采邑之主。"},{term:"餍",pinyin:["yàn"],meaning:"满足。不夺不餍：不夺取就不会满足。"},{term:"上下交征利",pinyin:["shàng","xià","jiāo","zhēng","lì"],meaning:"上上下下互相争夺利益。交：互相；征：求取。孟子的判断是：以利相召，则国危。"},{term:"后义而先利",pinyin:["hòu","yì","ér","xiān","lì"],meaning:"把义放在后面，把利放在前面。这是孟子要给国君纠正的次序。"}]}),n[1]||(n[1]=i("hr",null,null,-1)),n[2]||(n[2]=i("h3",{id:"二、贤者亦乐此乎",tabindex:"-1"},[e("二、贤者亦乐此乎 "),i("a",{class:"header-anchor",href:"#二、贤者亦乐此乎","aria-label":'Permalink to "二、贤者亦乐此乎"'},"​")],-1)),n[3]||(n[3]=i("p",null,[e("梁惠王站在池边看鸿雁麋鹿，问「贤者也以此为乐吗」。孟子的回答绕了个弯："),i("strong",null,"「贤者而后乐此，不贤者虽有此，不乐也。」"),e(" 他引《诗》说周文王筑灵台百姓踊跃，又引《汤誓》说百姓恨不得与夏桀同死——"),i("strong",null,"同样的台池鸟兽，一边是「与民偕乐」，一边是众叛亲离。")],-1)),t(s,{sections:m,glossary:h,"default-mode":"slips","aria-label":"孟子·梁惠王上·第二节 原文"}),t(a,{items:[{term:"沼",pinyin:["zhǎo"],meaning:"水池。王立于沼上：梁惠王站在池边看鸿雁麋鹿。"},{term:"麀鹿",pinyin:["yōu","lù"],meaning:"母鹿。麀：母兽。"},{term:"曷",pinyin:["hé"],meaning:"何时。时日曷丧：这个太阳什么时候才灭亡？（《汤誓》引文，人民诅咒夏桀之语）"},{term:"与民偕乐",pinyin:["yǔ","mín","xié","lè"],meaning:"和百姓一同快乐。偕：同。这是本节的正题，也是孟子仁政思想的一个侧面。"}]}),n[4]||(n[4]=i("hr",null,null,-1)),n[5]||(n[5]=i("h3",{id:"三、五十步笑百步",tabindex:"-1"},[e("三、五十步笑百步 "),i("a",{class:"header-anchor",href:"#三、五十步笑百步","aria-label":'Permalink to "三、五十步笑百步"'},"​")],-1)),n[6]||(n[6]=i("p",null,[e("梁惠王自认比邻国用心（「寡人之于国也，尽心焉耳矣」），孟子用战场上的例子一句话点破："),i("strong",null,"跑五十步的逃兵笑跑一百步的逃兵，性质是一样的。"),e(" 破完之后他给出正面方案——不违农时、数罟不入洿池、斧斤以时入山林，直到「五亩之宅，树之以桑」与「谨庠序之教」；而末段的「非我也，岁也」一语，把推责者的嘴脸写尽了。")],-1)),t(s,{sections:u,glossary:d,"default-mode":"slips","aria-label":"孟子·梁惠王上·第三节 原文"}),t(a,{items:[{term:"数罟",pinyin:["cù","gǔ"],meaning:"细密的渔网。数：密；罟：网。不入洿池：不许下到深池里（以免把小鱼也捞尽）。"},{term:"洿池",pinyin:["wū","chí"],meaning:"低洼的深水池。"},{term:"庠序",pinyin:["xiáng","xù"],meaning:"古代学校的名称。殷代称序，周代称庠。"},{term:"颁白者",pinyin:["bān","bái","zhě"],meaning:"颁：同「斑」。头发花白的老人。不负戴于道路：不必再在路上背负重物。"},{term:"莩",pinyin:["piǎo"],meaning:"同「殍」，饿死的人。涂有饿莩：路上有饿死的人。"},{term:"王道之始",pinyin:["wáng","dào","zhī","shǐ"],meaning:"王道的开端。孟子把「养生丧死无憾」当作王道的起点——先让百姓活得下去、死得安心。"}]}),n[7]||(n[7]=i("hr",null,null,-1)),n[8]||(n[8]=i("h3",{id:"四、率兽而食人",tabindex:"-1"},[e("四、率兽而食人 "),i("a",{class:"header-anchor",href:"#四、率兽而食人","aria-label":'Permalink to "四、率兽而食人"'},"​")],-1)),n[9]||(n[9]=i("p",null,[e("梁惠王说「愿安承教」，孟子的回答却一步比一步重：用棍棒杀人与用刀杀人无异，用刀杀人与用政治杀人也无异。接着就是全篇最锋利的一句——"),i("strong",null,"「庖有肥肉，厩有肥马，民有饥色，野有饿莩，此率兽而食人也。」"),e(" 他引孔子「始作俑者，其无后乎」，把「为民父母」四个字问到了底。")],-1)),t(s,{sections:p,glossary:y,"default-mode":"slips","aria-label":"孟子·梁惠王上·第四节 原文"}),t(a,{items:[{term:"梃",pinyin:["tǐng"],meaning:"棍棒。以梃与刃：用棍棒杀人和用刀杀人。"},{term:"俑",pinyin:["yǒng"],meaning:"殉葬用的木偶、陶俑。始作俑者，其无后乎：最早做俑来陪葬的人，该断子绝孙吧——因为俑像人形而用来殉葬。"},{term:"率兽而食人",pinyin:["shuài","shòu","ér","shí","rén"],meaning:"率领野兽来吃人。率：带领。指在上位者自己享受而让百姓饿死。"}]}),n[10]||(n[10]=i("hr",null,null,-1)),n[11]||(n[11]=i("h3",{id:"五、仁者无敌",tabindex:"-1"},[e("五、仁者无敌 "),i("a",{class:"header-anchor",href:"#五、仁者无敌","aria-label":'Permalink to "五、仁者无敌"'},"​")],-1)),n[12]||(n[12]=i("p",null,[e("梁惠王诉说国耻（东败于齐、西丧地于秦、南辱于楚），问怎么办。孟子给的方案是**「施仁政于民」"),i("strong",null,[e("——省刑罚、薄税敛、深耕易耨，再让壮者修孝悌忠信。他反过来说明对手的处境：「彼夺其民时……父母冻饿，兄弟妻子离散」——"),i("strong",null,"对方先失掉了民心，你去征讨，没有人会抵抗你。"),e(" 最后一句只有四个字：")]),e("「仁者无敌。」**")],-1)),t(s,{sections:b,glossary:x,"default-mode":"slips","aria-label":"孟子·梁惠王上·第五节 原文"}),t(a,{items:[{term:"耨",pinyin:["nòu"],meaning:"锄草。深耕易耨：深耕土地，及时除草。易：整治、及时。"},{term:"比死者一洒之",pinyin:["bǐ","sǐ","zhě","yī","xǐ","zhī"],meaning:"比：为、替。为所有战死者报仇雪耻一次。洒：同「洗」。"},{term:"仁者无敌",pinyin:["rén","zhě","wú","dí"],meaning:"行仁的人天下无敌。孟子不是说仁者武力强，而是说仁者不会成为众矢之的。"}]}),n[13]||(n[13]=i("hr",null,null,-1)),n[14]||(n[14]=i("h3",{id:"六、不嗜杀人者能一之",tabindex:"-1"},[e("六、不嗜杀人者能一之 "),i("a",{class:"header-anchor",href:"#六、不嗜杀人者能一之","aria-label":'Permalink to "六、不嗜杀人者能一之"'},"​")],-1)),n[15]||(n[15]=i("p",null,[e("孟子见梁襄王，出来评价「望之不似人君」。梁襄王问天下怎样才安定，孟子只答一个字："),i("strong",null,"「定于一。」"),e(" 再问谁能统一，答案更出人意料——"),i("strong",null,"「不嗜杀人者能一之。」"),e(" 这一节把政治的门槛降到了最低：不要求圣贤，只要求不把杀人当嗜好。末段以旱苗遇雨作喻，写百姓盼望仁君之切。")],-1)),t(s,{sections:z,glossary:j,"default-mode":"slips","aria-label":"孟子·梁惠王上·第六节 原文"}),t(a,{items:[{term:"浡然",pinyin:["bó","rán"],meaning:"兴起、蓬勃的样子。苗浡然兴之：禾苗蓬勃地生长起来。"},{term:"人牧",pinyin:["rén","mù"],meaning:"统治人民的人（牧：牧养，引申为治理）。"},{term:"不嗜杀人者能一之",pinyin:["bù","shì","shā","rén","zhě","néng","yī","zhī"],meaning:"不喜好杀人的，才能统一天下。嗜：爱好。这是孟子对「谁能得天下」最短的回答。"}]}),n[16]||(n[16]=i("hr",null,null,-1)),n[17]||(n[17]=i("h3",{id:"七、齐桓晋文之事",tabindex:"-1"},[e("七、齐桓晋文之事 "),i("a",{class:"header-anchor",href:"#七、齐桓晋文之事","aria-label":'Permalink to "七、齐桓晋文之事"'},"​")],-1)),n[18]||(n[18]=i("p",null,[e("全篇最长的一节，也是孟子论辩艺术的顶峰。齐宣王想问齐桓、晋文的霸业，孟子说没人讲过，还是谈王道吧。"),i("strong",null,"他从一件小事入手"),e("——宣王不忍看牛发抖，用羊换牛祭钟；由此推出「是心足以王矣」。再层层推进：能及禽兽而功不至百姓，是「不为也，非不能也」；真正的关键是「老吾老，以及人之老；幼吾幼，以及人之幼」；而宣王所求（辟土地、朝秦楚）与所做相反，是「缘木而求鱼」。最后落到具体的制度安排："),i("strong",null,"「五亩之宅，树之以桑……老者衣帛食肉，黎民不饥不寒，然而不王者，未之有也。」")],-1)),t(s,{sections:w,glossary:f,"default-mode":"slips","aria-label":"孟子·梁惠王上·第七节 原文"}),t(a,{items:[{term:"衅钟",pinyin:["xìn","zhōng"],meaning:"古代新钟铸成，杀牲取血涂在钟的缝隙上以祭，称衅钟。"},{term:"觳觫",pinyin:["hú","sù"],meaning:"因恐惧而颤抖的样子。吾不忍其觳觫：我不忍心看它吓得发抖。"},{term:"褊小",pinyin:["biǎn","xiǎo"],meaning:"狭小。齐国虽褊小：齐国虽然狭小。"},{term:"折枝",pinyin:["zhé","zhī"],meaning:"为老人折一根树枝（一说「枝」通「肢」，指按摩肢体）。喻极易做到的事。"},{term:"缘木而求鱼",pinyin:["yuán","mù","ér","qiú","yú"],meaning:"爬到树上去捉鱼。喻方向错了，白费力气。"},{term:"罔民",pinyin:["wǎng","mín"],meaning:"罔：同「网」，张网陷害。是罔民也：这是设罗网来陷害百姓。"},{term:"不为也，非不能也",pinyin:["bù","wéi","yě","fēi","bù","néng","yě"],meaning:"是不去做，不是做不到。孟子以此区分「挟太山以超北海」（真不能）与「为长者折枝」（不肯做）。"},{term:"老吾老，以及人之老",pinyin:["lǎo","wú","lǎo","yǐ","jí","rén","zhī","lǎo"],meaning:"尊敬自己的老人，进而推及别人的老人。下句「幼吾幼，以及人之幼」同此——这就是「推恩」。"}]}),n[19]||(n[19]=l('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《梁惠王上》七节，六节是孟子与君主的对答，一问一答之间，仁政的主张被反复推进。</p><p>七节的线索大致是：<strong>第一节立纲</strong>（何必曰利，只有仁义）；<strong>第二节与第三节说「与民同乐」和「先富后教」</strong>（贤者而后乐此；养生丧死无憾，王道之始）；<strong>第四、五节把话说到最重</strong>（率兽而食人；仁者无敌）；<strong>第六节给出一条极简的判准</strong>（不嗜杀人者能一之）；<strong>第七节是总论</strong>，从「以羊易之」的心理细节，推到「不为也，非不能也」，再推到「制民之产」的具体设计。</p><p><strong>七节合起来，是孟子政治思想的完整入口</strong>：从义利之辨起，到民生制度止。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它把全书的第一步踩在「义利之辨」上</strong>：「何必曰利？亦有仁义而已矣」——<strong>孟子的判断是：以利相召，上下交征利，国必危。</strong> 而他的话紧接着给了理由（「未有仁而遗其亲者也，未有义而后其君者也」），不是空喊。</li><li><strong>「五十步笑百步」是一次极漂亮的归谬</strong>：梁惠王自认比邻国用心，孟子用战场上的例子说明「程度不同而实质相同」。<strong>这一点破的方式，成了后世最常用的比喻之一。</strong></li><li><strong>它给出了仁政的可操作内容</strong>：不违农时、数罟不入洿池、斧斤以时入山林、五亩之宅树之以桑、百亩之田勿夺其时、谨庠序之教。<strong>「仁政」在这里不是口号，是一串具体安排。</strong></li><li><strong>「率兽而食人」是全书最锋利的一句</strong>：庖有肥肉、厩有肥马，民有饥色、野有饿莩——<strong>孔子说的「始作俑者其无后乎」，被孟子用来质问「为民父母」四个字。</strong></li><li><strong>「不嗜杀人者能一之」把政治的门槛降到了最低</strong>：不要求仁者、圣者，只要求**「不嗜杀人」**。</li><li><strong>「老吾老，以及人之老；幼吾幼，以及人之幼」是儒家推己及人的经典表述</strong>：与《论语》「己所不欲，勿施于人」互补——<strong>一个是消极的不加，一个是积极的推及。</strong></li><li><strong>末节的「不为也，非不能也」是对所有人最有用的一句</strong>：挟泰山超北海是真做不到，为长者折枝是不肯做。<strong>分清这两件事，很多借口就不成立了。</strong></li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「何必曰利」检查动机</strong>：把一个组织、一段关系、一个项目的动机摊开看——是「上下交征利」，还是有一个共同相信的东西？</li><li><strong>用「五十步笑百步」对自己</strong>：我是不是也在用「我比某人好一点」来证明自己没问题？<strong>程度之差不能代替性质之差。</strong></li><li><strong>用「不为也，非不能也」拆借口</strong>：这件事是真的做不到，还是「为长者折枝」我嫌麻烦？<strong>把这两类分开，行动会立刻清楚。</strong></li><li><strong>用「推恩」理解影响力</strong>：「老吾老，以及人之老」——<strong>能推及多远，影响力就有多大。</strong></li><li><strong>用「不嗜杀人者能一之」看待领导者</strong>：一个上位者最底线的品质是什么？孟子给的答案不是英明，是<strong>不嗜杀人</strong>（不以伤害他人为手段、为快意）。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《孟子》的第一篇，第一句话就是辩驳。</p><p>梁惠王见了孟子，开口就问：您老不远千里来，能给我们国家带来什么利益？孟子一开口就把话顶回去：<strong>大王，何必谈利？有仁义就够了。</strong></p><p>接着他说理：国君说怎样利我的国，大夫说怎样利我的家，普通人说怎样利我自己——上上下下都在争利，这个国家就危险了。从来没听说过讲仁的人会抛弃父母，也没听说过讲义的人会怠慢君主。<strong>大王只要讲仁义就够了，何必谈利？</strong></p><p>这一篇里有几个很出名的场景。梁惠王自认比邻国用心，孟子却说：就像战场上跑了五十步的人笑跑一百步的人，都是逃兵。他还给梁惠王算了一笔账：不误农时，粮食就吃不完；按时砍伐，木材就用不完；百姓养生送死没有遗憾，<strong>这就是王道的开端</strong>。</p><p>最重的一句是：「庖有肥肉，厩有肥马，民有饥色，野有饿莩，此率兽而食人也。」——<strong>你的厨房里有肥肉，马厩里有肥马，百姓却面有饥色、野外有饿死的人。这是领着野兽来吃人啊。</strong></p><p>最后一节最长，是孟子与齐宣王的对话。宣王问齐桓公、晋文公的事，孟子说没人讲过，还是谈王道吧。一路谈下去，从宣王不忍杀一头牛的小事，谈到他不肯施恩于百姓；孟子说了一句极实用的话：</p><p><strong>「挟太山以超北海」是真做不到；「为长者折枝」是不肯做。大王不实行王道，不是前者，是后者。</strong></p><p>最后落到具体的安排：让每家有五亩宅地种桑、有百亩田不误农时、办好学校教育。<strong>「老者衣帛食肉，黎民不饥不寒，然而不王者，未之有也。」</strong></p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「何必曰利？亦有仁义而已矣」——我所在的团队、家庭，「利」和「义」的次序是清楚的，还是混着的？</li><li>「五十步笑百步」——我有没有靠「比别人好一点」来安慰自己？</li><li>「不为也，非不能也」——我现在拖延的那件事，属于哪一类？如果是「折枝」，是什么让我不肯做？</li><li>「率兽而食人」——如果把这句当作一把尺子，它能量出什么？</li><li>「老吾老，以及人之老；幼吾幼，以及人之幼」——我能推及到多远？到家人、到朋友、到陌生人？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a></li><li>下篇：<a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-02">孟子·梁惠王下</a></li><li>参考：《孟子》朱熹《四书章句集注·孟子集注》；杨伯峻《孟子译注》</li></ul>',24))])}}});export{D as __pageData,C as default};
